(* [comment removed for export] *)
Definition WSIM (cw : PMR.ctrl) (ww : list Z) (wl : Z) (i : nat) (k : Z) : Prop :=
  match i with
  | 0%nat => True
  | 5%nat => PMR.skip_space cw ww = (PMR.set_st (PMR.push cw (PMR.c_st cw)) PML.ST_CR, [])
  | _ => exists n : nat, Z.of_nat n = wl - k /\ (n < length ww)%nat /\ PMR.skip_space cw ww = PMR.skip_space cw (skipn n ww) /\
         match i with 3%nat => nth n ww 0 = 13 | 4%nat => nth n ww 0 = 13 /\ nth (Datatypes.S n) ww 0 = 10 | _ => True end
  end.
