Section SkipSpaceOk.
Context {SCFG_P : ScfgP}.
Variable L : asan_layout.
Variable ar : asan_run.
Variable C : asan_statics_cells.
Variable HI : asan_iface.
Abbreviation IC := PMLA.C_xboth.
Hypothesis HIok : PmHeapIfaceA.asan_iface_ok L ar C SCFG HI.
Hypothesis LAY : L5A.as0_layout L C.
Hypothesis FOOTC : forall a, PMLA.in_foot IC a -> ~ hl_rt_static L a.              (* [comment removed for export] *)
Hypothesis FPM : forall (fx fx' : FPState) R pc M R' pc' M',
  msteps RSEGS (@mkst fx R (Z_to_bv 64 pc) M (seg_rom RSEGS)) (@mkst fx' R' (Z_to_bv 64 pc') M' (seg_rom RSEGS)) -> PMSA.fp_ok fx -> PMSA.fp_ok fx'.
Hypothesis VPUSH_OK : PMSA.vec_push_specA L ar HI SSA.PC_VPUSH.                    (* [comment removed for export] *)

Definition hid (P : Prop) : Prop := P.
(* [comment removed for export] *)
Definition WF (P a : Z) : Prop := P + 160 <= a < P + 184 \/ P + 200 <= a < P + 209.
(* [comment removed for export] *)
Definition CRD (bcap kx bx : Z) (cr : credit) (c : Z) : Prop :=
  0 <= kx /\ 0 <= bx /\
  (bcap <= 2 ^ 27 /\ (Z.log2 (2 ^ 27 / bcap) + Z.log2 (1056 / c)) * hl_k_per_malloc L <= fst cr - kx /\
   hl_b_lin L * ((2 ^ 28 - 2 * bcap) + (2112 - 2 * c)) + (Z.log2 (2 ^ 27 / bcap) + Z.log2 (1056 / c)) * hl_b_overhead L <= snd cr - bx).
Lemma crd_ps : forall kx bx cr ps, CRD (PML.ps_bcap ps) kx bx cr (PML.ps_scap ps) <-> PMLA.pcredit_xA L cr ps kx bx.
